function debounce(fn, wait, { leading = false, trailing = true } = {}) {
  let timer, lastResult;

  return function(...args) {
    const callNow = leading && !timer;

    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (trailing && !callNow) {
        lastResult = fn.apply(this, args);
      }
    }, wait);

    if (callNow) lastResult = fn.apply(this, args);
    return lastResult;
  };
}

// Leading: fires immediately, then silent for 'wait' ms
const search = debounce(callAPI, 300, { leading: true, trailing: false });
// Trailing: fires once after 'wait' ms of silence
